import os
import torch


class Config:
    """
    Centralized configuration for the Speech Command Recognition task.
    Includes file paths, audio processing parameters, model hyperparameters,
    and training settings.
    """

    # ==========================================
    # 1. File Paths and Directories
    # ==========================================
    INPUT_ROOT = "./input"
    METADATA_DIR = "./metadata"

    # Metadata files generated by the metadata script
    TRAIN_CSV = os.path.join(METADATA_DIR, "train.csv")
    VAL_CSV = os.path.join(METADATA_DIR, "val.csv")
    TEST_CSV = os.path.join(METADATA_DIR, "test.csv")

    # Working directory for artifacts (checkpoints, cache)
    WORKING_DIR = "./working/idea_14"
    os.makedirs(WORKING_DIR, exist_ok=True)

    # Model Checkpoint Path
    BEST_MODEL_PATH = os.path.join(WORKING_DIR, "best_model.pth")

    # Submission output
    SUBMISSION_DIR = "./submission"
    os.makedirs(SUBMISSION_DIR, exist_ok=True)
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # ==========================================
    # 2. Audio & Spectrogram Parameters
    # ==========================================
    # Audio Signal
    SAMPLE_RATE = 16000
    DURATION = 1.0  # seconds
    NUM_SAMPLES = int(SAMPLE_RATE * DURATION)

    # GPU-Native Spectrogram Generation (Log-Mel)
    # Using n_fft=1024 for spectral oversampling as per strategy
    N_FFT = 1024
    # Hop length 160 samples @ 16kHz = 10ms
    HOP_LENGTH = 160
    # Window length 400 samples @ 16kHz = 25ms
    WIN_LENGTH = 400
    # Number of Mel bands
    N_MELS = 128
    # Frequency limits
    F_MIN = 20
    F_MAX = 7800  # Slightly below Nyquist (8000)

    # ==========================================
    # 3. Label Configuration
    # ==========================================
    # The 12 specific labels required for the task
    LABELS = [
        "yes",
        "no",
        "up",
        "down",
        "left",
        "right",
        "on",
        "off",
        "stop",
        "go",
        "silence",
        "unknown",
    ]
    NUM_CLASSES = len(LABELS)

    # Mappings
    LABEL2ID = {label: i for i, label in enumerate(LABELS)}
    ID2LABEL = {i: label for i, label in enumerate(LABELS)}

    # ==========================================
    # 4. Model Architecture
    # ==========================================
    MODEL_NAME = "efficientnet_v2_b0"
    # Input channels to the backbone (spectrogram is 1 channel, but model might expect 3)
    # We will adapt the first layer to take 1 channel.
    IN_CHANNELS = 1

    # ==========================================
    # 5. Training Hyperparameters
    # ==========================================
    SEED = 42

    # Optimization
    # Small batch size for high update frequency
    BATCH_SIZE = 32
    EPOCHS = 50
    LEARNING_RATE = 1e-3
    WEIGHT_DECAY = 1e-2

    # Regularization
    LABEL_SMOOTHING = 0.1
    DROPOUT = 0.2

    # SpecAugment parameters (applied on GPU)
    FREQ_MASK_PARAM = 20
    TIME_MASK_PARAM = 40

    # ==========================================
    # 6. Compute & Execution
    # ==========================================
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    # Since we are using GPU-resident data, num_workers for DataLoader can be 0
    NUM_WORKERS = 0

    # ==========================================
    # 7. Debugging & Development
    # ==========================================
    # Set DEBUG to True to train on a small subset for quick pipeline verification
    DEBUG = False
    DEBUG_SUBSET_SIZE = 1000  # Number of samples to use in debug mode
